import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios'; // අපි මෙතනදී axios පාවිච්චි කරමු, වඩාත් පහසුයි

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [newPassword, setNewPassword] = useState(''); // අලුත් පාස්වර්ඩ් එක සඳහා
    const [error, setError] = useState('');
    const [showReset, setShowReset] = useState(false); // Reset Modal එක පෙන්නන්න
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('http://localhost:8081/login', { username, password });
            
            if (response.data.success) {
                localStorage.setItem('loggedInStudent', JSON.stringify(response.data.student));
                navigate('/dashboard');
            } else {
                setError(response.data.message);
            }
        } catch (err) {
            setError("Cannot connect to server!");
        }
    };

    const handleResetPassword = async () => {
        try {
            const response = await axios.post('http://localhost:8081/reset-password', { username, newPassword });
            if (response.data.status === "Success") {
                alert("✅ Password reset successfully!");
                setShowReset(false);
            } else {
                alert("❌ " + response.data.message);
            }
        } catch (err) {
            alert("Error connecting to server!");
        }
    };

    return (
        <div style={{ textAlign: 'center', marginTop: '50px' }}>
            <h2>Welcome to Aura Pen</h2>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            
            {/* ලොගින් ෆෝම් එක */}
            {!showReset ? (
                <form onSubmit={handleLogin}>
                    <input type="text" placeholder="Student ID" value={username} onChange={(e) => setUsername(e.target.value)} style={{ padding: '10px', display: 'block', margin: '10px auto' }} />
                    <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} style={{ padding: '10px', display: 'block', margin: '10px auto' }} />
                    <button type="submit" style={{ padding: '10px 20px', backgroundColor: 'green', color: 'white', cursor: 'pointer' }}>Login</button>
                    <br />
                    <button type="button" onClick={() => setShowReset(true)} style={{ marginTop: '10px', background: 'none', border: 'none', color: 'blue', textDecoration: 'underline', cursor: 'pointer' }}>
                        Forgot Password?
                    </button>
                </form>
            ) : (
                /* පාස්වර්ඩ් රිසෙට් ෆෝම් එක */
                <div style={{ border: '1px solid #ccc', padding: '20px', width: '300px', margin: 'auto' }}>
                    <h3>Reset Password</h3>
                    <input type="text" placeholder="Enter Username" onChange={(e) => setUsername(e.target.value)} style={{ padding: '10px', display: 'block', margin: '10px auto' }} />
                    <input type="password" placeholder="Enter New Password" onChange={(e) => setNewPassword(e.target.value)} style={{ padding: '10px', display: 'block', margin: '10px auto' }} />
                    <button onClick={handleResetPassword} style={{ padding: '10px 20px', backgroundColor: 'orange', color: 'white', cursor: 'pointer' }}>Reset Now</button>
                    <button onClick={() => setShowReset(false)} style={{ padding: '10px 20px', marginLeft: '5px', cursor: 'pointer' }}>Back</button>
                </div>
            )}
        </div>
    );
};

export default Login;
